import { Flex, FlexProps, Image, ImageProps } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import TokenPlaceholder from '/images/token_placeholder.png'

interface TokenImgProps {
  src: string
  wrapStyle?: FlexProps
  imageStyle?: ImageProps
  onClick?: () => void
}

export default function TokenImg({ src, wrapStyle = { p: '40px' }, imageStyle = {}, onClick }: TokenImgProps) {
  const [imgSrc, setImgSrc] = useState(TokenPlaceholder)
  useEffect(() => {
    if (src && src !== '') {
      const img = new window.Image() as HTMLImageElement
      img.src = src
      img.onload = () => setImgSrc(src)
      img.onerror = () => setImgSrc(TokenPlaceholder)
    } else {
      setImgSrc(TokenPlaceholder)
    }
  }, [src])
  return (
    <Flex
      cursor={onClick ? 'pointer' : undefined}
      w="100%"
      h="100%"
      minW="100%"
      minH="100%"
      margin="auto"
      borderRadius="20px"
      align="center"
      justifyContent="center"
      zIndex="2"
      bg="bg_primary"
      onClick={onClick}
      backgroundSize="100% 100%"
      {...wrapStyle}
      p={imgSrc == TokenPlaceholder ? wrapStyle?.p : ''}
    >
      {/*
        objectFit="cover"
        objectPosition="center" */}
      <Image
        className={imgSrc == TokenPlaceholder ? 'token_img' : ''}
        src={imgSrc || TokenPlaceholder}
        w="100%"
        h="100%"
        borderRadius="20px"
        {...imageStyle}
      />
    </Flex>
  )
}
